// Parse and enhance AI vision analysis
const aiResponse = $input.first().json;
const originalData = $('Webhook - Floor Plan Upload').first().json;

// Try to parse AI response as JSON, fallback to text processing
let analysisData;
try {
  analysisData = typeof aiResponse.choices[0].message.content === 'string' 
    ? JSON.parse(aiResponse.choices[0].message.content)
    : aiResponse.choices[0].message.content;
} catch (e) {
  // Fallback text processing
  const content = aiResponse.choices[0].message.content;
  analysisData = {
    rawAnalysis: content,
    parsed: false
  };
}

// Generate electrical markup coordinates
function generateElectricalMarkup(rooms) {
  const markup = [];
  const symbols = {
    outlet: '⚡',
    switch: '🔘', 
    fixture: '💡',
    panel: '📦',
    gfci: '🛡️'
  };

  if (!rooms || !Array.isArray(rooms)) {
    return markup;
  }

  rooms.forEach((room, index) => {
    const baseX = 100 + (index % 3) * 200;
    const baseY = 100 + Math.floor(index / 3) * 150;

    // Add outlets based on room type
    const outletCount = {
      'living': 6,
      'bedroom': 4,
      'kitchen': 8,
      'bathroom': 2,
      'office': 4,
      'dining': 2
    }[room.type?.toLowerCase()] || 3;

    for (let i = 0; i < outletCount; i++) {
      markup.push({
        type: 'outlet',
        symbol: symbols.outlet,
        coordinates: {
          x: baseX + (i * 30),
          y: baseY + 20,
          grid: `${String.fromCharCode(65 + Math.floor((baseX + i * 30) / 50))}${Math.floor((baseY + 20) / 25)}`
        },
        room: room.name,
        specifications: {
          type: room.type === 'bathroom' || room.type === 'kitchen' ? 'GFCI' : 'Standard',
          circuit: `Circuit ${Math.floor(index / 2) + 1}`,
          amperage: '15A'
        }
      });
    }

    // Add switches
    markup.push({
      type: 'switch',
      symbol: symbols.switch,
      coordinates: {
        x: baseX - 20,
        y: baseY,
        grid: `${String.fromCharCode(65 + Math.floor((baseX - 20) / 50))}${Math.floor(baseY / 25)}`
      },
      room: room.name,
      specifications: {
        type: 'Single Pole',
        controls: 'Room Lighting'
      }
    });

    // Add fixtures
    markup.push({
      type: 'fixture',
      symbol: symbols.fixture,
      coordinates: {
        x: baseX + 50,
        y: baseY - 30,
        grid: `${String.fromCharCode(65 + Math.floor((baseX + 50) / 50))}${Math.floor((baseY - 30) / 25)}`
      },
      room: room.name,
      specifications: {
        type: 'LED Ceiling',
        wattage: room.type === 'kitchen' ? '60W' : '40W'
      }
    });
  });

  return markup;
}

// Calculate load requirements
function calculateRoomLoads(rooms) {
  if (!rooms || !Array.isArray(rooms)) {
    return { totalLoad: 3000, breakdown: [] };
  }

  const loadFactors = {
    'living': 3.0,
    'bedroom': 2.5,
    'kitchen': 7.5,
    'bathroom': 3.5,
    'office': 4.0,
    'dining': 2.5,
    'laundry': 5.0
  };

  let totalLoad = 0;
  const breakdown = rooms.map(room => {
    const area = room.dimensions?.area || 150; // Default 150 sq ft
    const factor = loadFactors[room.type?.toLowerCase()] || 3.0;
    const load = Math.round(area * factor);
    totalLoad += load;

    return {
      room: room.name,
      type: room.type,
      area,
      loadFactor: factor,
      calculatedLoad: load
    };
  });

  return { totalLoad, breakdown };
}

// Generate compliance checklist
function generateComplianceChecklist(rooms, markup) {
  const checklist = [
    {
      code: 'NEC 210.52(A)',
      requirement: 'Outlet spacing ≤6 feet',
      status: 'review_required',
      locations: markup.filter(m => m.type === 'outlet').map(m => m.coordinates.grid)
    },
    {
      code: 'NEC 210.8(A)',
      requirement: 'GFCI protection in bathrooms',
      status: markup.some(m => m.room?.toLowerCase().includes('bathroom') && m.specifications?.type === 'GFCI') ? 'compliant' : 'non_compliant',
      locations: markup.filter(m => m.room?.toLowerCase().includes('bathroom')).map(m => m.coordinates.grid)
    },
    {
      code: 'NEC 210.8(A)', 
      requirement: 'GFCI protection in kitchens',
      status: markup.some(m => m.room?.toLowerCase().includes('kitchen') && m.specifications?.type === 'GFCI') ? 'compliant' : 'non_compliant',
      locations: markup.filter(m => m.room?.toLowerCase().includes('kitchen')).map(m => m.coordinates.grid)
    },
    {
      code: 'NEC 210.12(A)',
      requirement: 'AFCI protection in living areas',
      status: 'review_required',
      note: 'Verify AFCI breakers in panel'
    }
  ];

  return checklist;
}

// Process the analysis
const rooms = analysisData.rooms || [];
const electricalMarkup = generateElectricalMarkup(rooms);
const loadCalculations = calculateRoomLoads(rooms);
const complianceChecklist = generateComplianceChecklist(rooms, electricalMarkup);

// Generate construction instructions
const constructionGuide = {
  phases: [
    {
      phase: 1,
      name: 'Rough-In Electrical',
      tasks: electricalMarkup.map(item => ({
        location: `Grid ${item.coordinates.grid} (${item.coordinates.x}", ${item.coordinates.y}")`,
        action: `Install ${item.type}`,
        specifications: item.specifications,
        room: item.room
      }))
    },
    {
      phase: 2,
      name: 'Panel and Circuit Configuration',
      tasks: [
        {
          location: 'Main Panel',
          action: 'Install circuit breakers',
          specifications: {
            totalCircuits: Math.ceil(electricalMarkup.length / 8),
            panelSize: loadCalculations.totalLoad > 15000 ? '200A' : '100A'
          }
        }
      ]
    },
    {
      phase: 3,
      name: 'Final Installation',
      tasks: [
        'Install outlet and switch covers',
        'Test all circuits',
        'Verify GFCI/AFCI operation',
        'Complete electrical inspection'
      ]
    }
  ]
};

const result = {
  projectId: originalData.projectId || `FP-${Date.now()}`,
  timestamp: new Date().toISOString(),
  floorPlanAnalysis: {
    aiAnalysis: analysisData,
    rooms: rooms.length,
    electricalElements: electricalMarkup.length
  },
  electricalMarkup,
  loadCalculations,
  complianceChecklist,
  constructionGuide,
  summary: {
    totalOutlets: electricalMarkup.filter(m => m.type === 'outlet').length,
    totalSwitches: electricalMarkup.filter(m => m.type === 'switch').length,
    totalFixtures: electricalMarkup.filter(m => m.type === 'fixture').length,
    estimatedLoad: loadCalculations.totalLoad,
    complianceScore: Math.round((complianceChecklist.filter(c => c.status === 'compliant').length / complianceChecklist.length) * 100)
  },
  generatedBy: 'ElectricalAI Pro Floor Plan Analyzer',
  version: '1.0.0'
};

return [{ json: result }];

// Generate field crew instructions
const data = $input.first().json;

// Create detailed installation guide
const fieldInstructions = {
  projectId: data.projectId,
  title: 'Electrical Installation Guide',
  overview: {
    totalElements: data.summary.totalOutlets + data.summary.totalSwitches + data.summary.totalFixtures,
    estimatedHours: Math.ceil((data.summary.totalOutlets * 0.5) + (data.summary.totalSwitches * 0.3) + (data.summary.totalFixtures * 0.8)),
    crewSize: data.summary.totalOutlets > 20 ? 3 : 2,
    estimatedDays: Math.ceil(((data.summary.totalOutlets * 0.5) + (data.summary.totalSwitches * 0.3) + (data.summary.totalFixtures * 0.8)) / 8)
  },
  installation: data.constructionGuide.phases.map(phase => ({
    ...phase,
    estimatedHours: phase.tasks.length * 0.5,
    tools: [
      'Drill with bits',
      'Wire strippers', 
      'Voltage tester',
      'Fish tape',
      'Level'
    ],
    safety: [
      'Turn off power at main panel',
      'Test circuits with voltage tester',
      'Use proper PPE',
      'Follow lockout/tagout procedures'
    ]
  })),
  gridReference: {
    description: 'Use grid coordinates for precise positioning',
    example: 'Grid B3 means 6.5" from left edge, 2.0" down from reference point',
    coordinates: data.electricalMarkup.map(item => ({
      grid: item.coordinates.grid,
      position: `${item.coordinates.x}" x ${item.coordinates.y}"`,
      type: item.type,
      room: item.room,
      specs: item.specifications
    }))
  },
  qualityChecks: [
    'Verify all connections are tight',
    'Test GFCI outlets with test button',
    'Check switch operation',
    'Measure voltage at all outlets',
    'Verify proper grounding'
  ],
  complianceNotes: data.complianceChecklist.map(item => ({
    code: item.code,
    requirement: item.requirement,
    status: item.status,
    action: item.status === 'non_compliant' ? 'MUST FIX' : 'VERIFY'
  }))
};

const response = {
  success: true,
  projectId: data.projectId,
  analysis: {
    rooms: data.floorPlanAnalysis.rooms,
    elements: data.electricalMarkup.length,
    estimatedLoad: data.loadCalculations.totalLoad,
    complianceScore: data.summary.complianceScore
  },
  markup: data.electricalMarkup,
  fieldGuide: fieldInstructions,
  nextSteps: [
    'Review markup with project manager',
    'Generate material list',
    'Schedule electrical rough-in',
    'Coordinate with other trades'
  ],
  timestamp: data.timestamp
};

return [{ json: response }];
